ALTER TABLE "crawl_page_extractions" ADD CONSTRAINT "page_extract_encoding_provenance_check" CHECK (("crawl_page_extractions"."character_encoding_source" is null and "crawl_page_extractions"."character_encoding_declared" is null and "crawl_page_extractions"."character_encoding_declaration_offset" is null) or ("crawl_page_extractions"."character_encoding_source" in ('bom', 'http_header', 'meta', 'default') and "crawl_page_extractions"."character_encoding" is not null and (("crawl_page_extractions"."character_encoding_source" = 'meta' and "crawl_page_extractions"."character_encoding_declaration_offset" between 0 and 2048) or ("crawl_page_extractions"."character_encoding_source" <> 'meta' and "crawl_page_extractions"."character_encoding_declaration_offset" is null))));